            Locale.setDefault(locale);
            checkVersionsEqual("1-abcdefghijklmnopqrstuvwxyz", "1-ABCDEFGHIJKLMNOPQRSTUVWXYZ");
        }
    } finally {
        Locale.setDefault(orig);
    }
}

