    assertVersionOlder("1.0-1", "1.0-2");
    assertVersionEqual("2.0-0", "2.0");
    assertVersionOlder("2.0", "2.0-1");
    assertVersionOlder("2.0.0", "2.0-1");
    assertVersionOlder("2.0-1", "2.0.1");
