    assertEquals("RHS-ONLY", getNthChild(mergeResult, "property", 2).getChild("name").getValue());
    assertEquals("right", p2.getChild("name").getInputLocation());
    assertEquals("RHS", getNthChild(mergeResult, "property", 2).getChild("value").getValue());
    assertEquals("right", p2.getChild("value").getInputLocation());
}

